style.css:
@-moz-document url-prefix("https://www.khanacademy.org") {
/* Replace the light-blue practice background */
._1yh3tti {
    background-color: #0a2665 !important;   /* old KA navy */
}
/* Replace the light-blue practice background with navy */
._1y3pxpe5 {
    background-color: #0a2665 !important;
}
/* Completion screen splash background */
div[data-testid="exercise-task-card-do-n"],
div[data-testid="exercise-task-card-do-n"] > div,
div[data-testid="exercise-task-card-do-n"] *[aria-hidden="true"] {
    background-color: #0a2665 !important;
}
}
